(function(){console.log("Pilot Bridge (Isolated World) loaded");window.addEventListener("message",o=>{if(o.source!==window||!o.data||o.data.source!=="PILOT_SCRIPT")return;const{action:e,payload:a}=o.data;chrome.runtime.sendMessage({type:"PILOT_BRIDGE_ACTION",action:e,payload:a}).catch(r=>console.error("Pilot Bridge Error:",r))});window.Pilot={openTab:o=>{chrome.runtime.sendMessage({type:"PILOT_BRIDGE_ACTION",action:"openTab",payload:{url:o}})},log:o=>console.log("[Pilot]",o),workflow:{next:o=>{chrome.runtime.sendMessage({type:"PILOT_BRIDGE_ACTION",action:"workflowNext",payload:{data:o}})},finish:()=>{chrome.runtime.sendMessage({type:"PILOT_BRIDGE_ACTION",action:"workflowFinish",payload:{}})},fail:o=>{chrome.runtime.sendMessage({type:"PILOT_BRIDGE_ACTION",action:"workflowFail",payload:{reason:o}})}}};
})()